import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

avg_pool3d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void avg_pool3d_kernel(
    const float* input,
    float* output,
    int batch_size,
    int channels,
    int input_depth,
    int input_height,
    int input_width,
    int output_depth,
    int output_height,
    int output_width,
    int kernel_size,
    int stride,
    int padding
) {
    int total_elements = batch_size * channels * output_depth * output_height * output_width;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx >= total_elements) return;

    int b = idx / (channels * output_depth * output_height * output_width);
    int rem = idx % (channels * output_depth * output_height * output_width);
    int c = rem / (output_depth * output_height * output_width);
    rem %= (output_depth * output_height * output_width);
    int od = rem / (output_height * output_width);
    rem %= (output_height * output_width);
    int oh = rem / output_width;
    int ow = rem % output_width;

    int start_d = od * stride - padding;
    int start_h = oh * stride - padding;
    int start_w = ow * stride - padding;

    float sum = 0.0f;

    for (int kd = 0; kd < kernel_size; ++kd) {
        int id = start_d + kd;
        if (id < 0 || id >= input_depth) continue;
        for (int kh = 0; kh < kernel_size; ++kh) {
            int ih = start_h + kh;
            if (ih < 0 || ih >= input_height) continue;
            for (int kw = 0; kw < kernel_size; ++kw) {
                int iw = start_w + kw;
                if (iw < 0 || iw >= input_width) continue;

                int input_idx = b * channels * input_depth * input_height * input_width +
                                c * input_depth * input_height * input_width +
                                id * input_height * input_width +
                                ih * input_width +
                                iw;
                sum += input[input_idx];
            }
        }
    }

    output[idx] = sum / (kernel_size * kernel_size * kernel_size);
}

torch::Tensor elementwise_avg_pool3d_cuda(torch::Tensor x, int kernel_size, int stride, int padding) {
    x = x.contiguous();
    int batch_size = x.size(0);
    int channels = x.size(1);
    int input_depth = x.size(2);
    int input_height = x.size(3);
    int input_width = x.size(4);

    int output_depth = (input_depth + 2*padding - kernel_size)/stride + 1;
    int output_height = (input_height + 2*padding - kernel_size)/stride + 1;
    int output_width = (input_width + 2*padding - kernel_size)/stride + 1;

    auto output = torch::zeros({batch_size, channels, output_depth, output_height, output_width}, x.options());
    int total_elements = output.numel();

    const int block_size = 256;
    int grid_size = (total_elements + block_size - 1) / block_size;

    avg_pool3d_kernel<<<grid_size, block_size>>>(
        x.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        channels,
        input_depth,
        input_height,
        input_width,
        output_depth,
        output_height,
        output_width,
        kernel_size,
        stride,
        padding
    );

    return output;
}
"""

avg_pool3d_cpp_source = "torch::Tensor elementwise_avg_pool3d_cuda(torch::Tensor x, int kernel_size, int stride, int padding);"

elementwise_avg_pool3d = load_inline(
    name='elementwise_avg_pool3d',
    cpp_sources=avg_pool3d_cpp_source,
    cuda_sources=avg_pool3d_source,
    functions=['elementwise_avg_pool3d_cuda'],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[],
)

class ModelNew(nn.Module):
    def __init__(self, kernel_size: int, stride: int = None, padding: int = 0):
        super().__init__()
        self.kernel_size = kernel_size
        self.stride = stride if stride is not None else kernel_size
        self.padding = padding
        self.custom_pool = elementwise_avg_pool3d

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.custom_pool.elementwise_avg_pool3d_cuda(x, self.kernel_size, self.stride, self.padding)
